def sequential_search(arr, element):
    """
    Perform a sequential (linear) search for element in arr.

    Returns:
        (True, index) if element is found, where index is the position
        of the first occurrence.
        (False, -1) if element is not found (including when arr is empty).
    """
    for index, value in enumerate(arr):
        if value == element:
            return (True, index)
    return (False, -1)
```

