def count_Pairs(arr, n=None):
    if n is None:
        n = len(arr)
    arr = arr[:n]
    m = len(arr)
    freq = {}
    for x in arr:
        freq[x] = freq.get(x, 0) + 1
    total = m * (m - 1) // 2
    equal = sum(c * (c - 1) // 2 for c in freq.values())
    return total - equal
```

