def maxAverageOfPath(matrix):
    n = len(matrix)
    if n == 0:
        return 0.0
    # Every path from top-left to bottom-right moving only right/down
    # visits exactly 2*n - 1 cells, so maximizing the average is
    # equivalent to maximizing the total cost.
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = matrix[0][0]
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            best = float('-inf')
            if i > 0:
                best = max(best, dp[i - 1][j])
            if j > 0:
                best = max(best, dp[i][j - 1])
            dp[i][j] = matrix[i][j] + best
    return dp[n - 1][n - 1] / (2 * n - 1)
```

