def frequency_lists(list_of_lists):
    """
    Return a dictionary with the frequency of each element
    in a flattened list of lists.

    Args:
        list_of_lists: An iterable of iterables whose elements are hashable.

    Returns:
        A dict mapping each element to its total occurrence count.

    Examples:
        >>> frequency_lists([[1, 2, 3, 2], [4, 5, 6, 2], [7, 8, 9, 5]])
        {1: 1, 2: 3, 3: 1, 4: 1, 5: 2, 6: 1, 7: 1, 8: 1, 9: 1}
        >>> frequency_lists([])
        {}
        >>> frequency_lists([[], []])
        {}
    """
    frequency = {}
    for sublist in list_of_lists:
        for element in sublist:
            frequency[element] = frequency.get(element, 0) + 1
    return frequency
